        /// <param name="window">an <c>SDL_Window</c>.</param>
        /// <returns>
        /// <para>(bool) Returns true on success, or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>This function should only be called from the thread that created the window.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_ClaimWindowForGPUDevice">SDL_ClaimWindowForGPUDevice</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.GPU.GPURenderer.WaitAndAcquireSwapchainTexture">WaitAndAcquireSwapchainTexture</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPUDevice.ReleaseWindow">ReleaseWindow</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPURenderer.WindowSupportsPresentMode">WindowSupportsPresentMode</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPURenderer.WindowSupportsSwapchainComposition">WindowSupportsSwapchainComposition</see></seealso>
        public static extern void ClaimWindowForGPUDevice();

        /// <summary>
        /// <para>Performs a buffer-to-buffer copy.</para>
        /// </summary>
        /// <remarks>
        /// <para>This copy occurs on the GPU timeline. You may assume the copy has finished in subsequent commands.</para>
        /// </remarks>
        /// <param name="copy_pass">a copy pass handle.</param>
        /// <param name="source">the buffer and offset to copy from.</param>
        /// <param name="destination">the buffer and offset to copy to.</param>
        /// <param name="size">the length of the buffer to copy.</param>
        /// <param name="cycle">if true, cycles the destination buffer if it is already bound, otherwise overwrites the data.</param>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_CopyGPUBufferToBuffer">SDL_CopyGPUBufferToBuffer</seealso></SDLWiki>
        public static extern void CopyGPUBufferToBuffer();

        /// <summary>
        /// <para>Performs a texture-to-texture copy.</para>
        /// </summary>
        /// <remarks>
        /// <para>This copy occurs on the GPU timeline. You may assume the copy has finished in subsequent commands.</para>
        /// <para>This function does not support copying between depth and color textures. For those, copy the texture to a buffer and then to the destination texture.</para>
        /// </remarks>
        /// <param name="copy_pass">a copy pass handle.</param>
        /// <param name="source">a source texture region.</param>
        /// <param name="destination">a destination texture region.</param>
        /// <param name="w">the width of the region to copy.</param>
        /// <param name="h">the height of the region to copy.</param>
        /// <param name="d">the depth of the region to copy.</param>
        /// <param name="cycle">if true, cycles the destination texture if the destination texture is bound, otherwise overwrites the data.</param>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_CopyGPUTextureToTexture">SDL_CopyGPUTextureToTexture</seealso></SDLWiki>
        public static extern void CopyGPUTextureToTexture();

        /// <summary>
        /// <para>Creates a buffer object to be used in graphics or compute workflows.</para>
        /// </summary>
        /// <remarks>
        /// <para>The contents of this buffer are undefined until data is written to the buffer.</para>
        /// <para>Note that certain combinations of usage flags are invalid. For example, a buffer cannot have both the VERTEX and INDEX flags.</para>
        /// <para>If you use a STORAGE flag, the data in the buffer must respect std140 layout conventions. In practical terms this means you must ensure that vec3 and vec4 fields are 16-byte aligned.</para>
        /// <para>For better understanding of underlying concepts and memory management with SDL GPU API, you may refer <a href="https://moonside.games/posts/sdl-gpu-concepts-cycling/">this blog post</a> .</para>
        /// <para>There are optional properties that can be provided through <c>props</c>. These are the supported properties:</para>
        /// <list type="bullet">
        /// <item><description><see cref="CSDL.Props.GPUBufferCreateNameString">GPUBufferCreateNameString</see>: a name that can be displayed in debugging tools.</description></item>
        /// </list>
        /// </remarks>
        /// <param name="device">a GPU Context.</param>
        /// <param name="createinfo">a struct describing the state of the buffer to create.</param>
        /// <returns>
        /// <para>(<c>SDL_GPUBuffer</c> *) Returns a buffer object on success, or NULL on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_CreateGPUBuffer">SDL_CreateGPUBuffer</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.GPU.GPURenderer.UploadToBuffer">UploadToBuffer</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPUCopyPass.DownloadFromGPUBuffer">DownloadFromGPUBuffer</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPURenderer.CopyBufferToBuffer">CopyBufferToBuffer</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPURenderPass.BindVertexBuffers">BindVertexBuffers</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPURenderPass.BindIndexBuffer">BindIndexBuffer</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPURenderPass.BindVertexStorageBuffers">BindVertexStorageBuffers</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPURenderPass.BindFragmentStorageBuffers">BindFragmentStorageBuffers</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPURenderPass.DrawIndirect">DrawIndirect</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPURenderPass.DrawIndexedIndirect">DrawIndexedIndirect</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPUComputePass.BindComputeStorageBuffers">BindComputeStorageBuffers</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPUComputePass.DispatchIndirect">DispatchIndirect</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPUBuffer.DisposeResource">DisposeResource</see></seealso>
        public static extern void CreateGPUBuffer();

        /// <summary>
        /// <para>Creates a pipeline object to be used in a compute workflow.</para>
        /// </summary>
        /// <remarks>
        /// <para>Shader resource bindings must be authored to follow a particular convention depending on the shader format. See below for details.</para>
        /// <para>---</para>
        /// <para>**SPIR-V**</para>
        /// <para>For compute shaders, use:</para>
        /// <list type="bullet">
        /// <item><description>Set 0 for samplers, read-only storage textures, and read-only storage buffers</description></item>
        /// <item><description>Set 1 for read-write storage textures and read-write storage buffers</description></item>
        /// <item><description>Set 2 for uniform data</description></item>
        /// </list>
        /// <para>The first resource in a given set must have a <c>binding</c> of 0. Additional resources must appear at consecutive bindings (1, 2, etc), leaving no gaps in the set.</para>
        /// <para>All samplers must come first in the binding order of Set 0, in order of how they are bound via <c>SDL_BindGPUComputeSamplers()</c>.</para>
        /// <para>All read-only storage textures must come after all samplers in the binding order, in order of how they are bound via <c>SDL_BindGPUComputeStorageTextures()</c>.</para>
        /// <para>All read-only storage buffers must come after all read-only storage textures in the binding order, in order of how they are bound via <c>SDL_BindGPUComputeStorageBuffers()</c>.</para>
        /// <para>All read-write storage textures must come first in the binding order of Set 1, in order of how they are bound via <c>SDL_BeginGPUComputePass()</c>.</para>
        /// <para>All read-write storage buffers must come after all read-write storage textures in the binding order, in order of how they are bound via <c>SDL_BeginGPUComputePass()</c>.</para>
        /// <para>**Example**</para>
        /// <para>If a compute shader binds 2 of each resource type, its binding layout should look like this:</para>
        /// <code language="glsl">
        /// // Any samplers come first in Set 0, in SDL bind slot order
        /// layout(set = 0, binding = 0) sampler2d samplerBoundToSlot0;
        /// layout(set = 0, binding = 1) sampler2d samplerBoundToSlot1;
        /// // Any read-only storage textures come next in Set 0, in SDL bind slot order
        /// layout(set = 0, binding = 2) image2d storageTextureBoundToSlot0;
        /// layout(set = 0, binding = 3) image2d storageTextureBoundToSlot1;
        /// // Any read-only storage buffers come next in Set 0, in SDL bind slot order
        /// layout(set = 0, binding = 4) buffer storageBufferBoundToSlot0;
        /// layout(set = 0, binding = 5) buffer storageBufferBoundToSlot1;
        /// // Any read-write storage textures come first in Set 1, in SDL bind slot order
        /// layout(set = 1, binding = 0) image2d rwStorageTextureBoundToSlot0;
        /// layout(set = 1, binding = 1) image2d rwStorageTextureBoundToSlot1;
        /// // Any read-write storage buffers come next in Set 1, in SDL bind slot order
        /// layout(set = 1, binding = 2) buffer rwStorageBufferBoundToSlot0;
        /// layout(set = 1, binding = 3) buffer rwStorageBufferBoundToSlot1;
        /// // Any uniform buffers are in Set 2, in SDL slot order
        /// layout(set = 2, binding = 0) uniform UniformDataBoundToSlot0 {};
        /// layout(set = 2, binding = 1) uniform UniformDataBoundToSlot1 {};
        /// </code>
        /// <para>---</para>
        /// <para>**DXBC / DXIL (HLSL)**</para>
        /// <para>For compute shaders, use:</para>
        /// <list type="bullet">
        /// <item><description><c>(t[n], space0)</c> for sampled textures, read-only storage textures, and read-only storage buffers</description></item>
        /// <item><description><c>(s[n], space0)</c> for samplers</description></item>
        /// <item><description><c>(u[n], space1)</c> for read-write storage textures and read-write storage buffers</description></item>
        /// <item><description><c>(b[n], space2)</c> for uniform data</description></item>
        /// </list>
        /// <para>The first resource in a given register set must have a register index of <c>0</c>. Additional resources must appear at consecutive indices (1, 2, etc), leaving no gaps in the register set.</para>
        /// <para>All sampled textures must come first in the <c>t</c> register set, in order of how they are bound via <c>SDL_BindGPUComputeSamplers()</c>.</para>
        /// <para>All sampler objects must be in the <c>s</c> register set, in the same order as the textures above.</para>
        /// <para>All read-only storage textures must come after all samplers in the <c>t</c> register set, in order of how they are bound via <c>SDL_BindComputeStorageTextures()</c>.</para>
        /// <para>All read-only storage buffers must come after all storage textures in the <c>t</c> register set, in order of how they are bound via <c>SDL_BindComputeStorageBuffers()</c>.</para>
        /// <para>All read-write storage textures must come first in the <c>u</c> register set in <c>space1</c>, in order of how they are bound via <c>SDL_BeginGPUComputePass()</c>.</para>
        /// <para>All read-write storage buffers must come after all read-write storage textures in the <c>u</c> register set in <c>space1</c>, in order of how they are bound via <c>SDL_BeginGPUComputePass()</c>.</para>
        /// <para>**Example**</para>
        /// <para>If a compute shader binds 2 of each resource type, the layout should look like this:</para>
        /// <code language="c">
        /// // Any samplers and sampled textures come first in their respective register sets, in SDL bind slot order
        /// SamplerState SamplerBoundToSlot0 : register( s0, space0 );
        /// SamplerState SamplerBoundToSlot1 : register( s1, space0 );
        /// Texture2D SampledTextureBoundToSlot0 : register( t0, space0 );
        /// Texture2D SampledTextureBoundToSlot1 : register( t1, space0 );
        /// // Any read-only storage textures come next in the `t` register set, in SDL bind slot order
        /// Texture2D StorageTextureBoundToSlot0 : register( t2, space0 );
        /// Texture2D StorageTextureBoundToSlot1 : register( t3, space0 );
        /// // Any read-only storage buffers come next in the `t` register set, in SDL bind slot order
        /// ByteAddressBuffer StorageBufferBoundToSlot0 : register( t4, space0 );
        /// ByteAddressBuffer StorageBufferBoundToSlot1 : register( t5, space0 );
        /// // Any read-write storage textures come first in the `u` register set in space1, in SDL bind slot order
        /// RWTexture2D RWStorageTextureBoundToSlot0 : register( u0, space1 );
        /// RWTexture2D RWStorageTextureBoundToSlot1 : register( u1, space1 );
        /// // Any read-write storage buffers come next in the `u` register set in space1, in SDL bind slot order
        /// RWByteAddressBuffer RWStorageTextureBoundToSlot0 : register( u2, space1 );
        /// RWByteAddressBuffer RWStorageTextureBoundToSlot1 : register( u3, space1 );
        /// // Any uniform buffers are in the `b` register set in space2, in SDL slot order
        /// cbuffer UniformDataBoundToSlot0 : register( b0, space2 ) { ... };
        /// cbuffer UniformDataBoundToSlot1 : register( b1, space2 ) { ... };
        /// </code>
        /// <para>---</para>
        /// <para>**MSL / Metallib (Metal Shading Language)**</para>
        /// <para>The first resource in a given argument table must have an index of <c>0</c>. Additional resources must appear at consecutive indices (1, 2, etc), leaving no gaps in the table.</para>
        /// <para>All sampled textures must come first in the <c>[[texture]]</c> argument table, in order of how they are bound via <c>SDL_BindGPUComputeSamplers()</c>.</para>
        /// <para>All sampler objects must be in the <c>[[sampler]]</c> argument table, in the same order as the textures above.</para>
        /// <para>All read-only storage textures must come after all sampled textures in the <c>[[texture]]</c> argument table, in order of how they are bound via <c>SDL_BindGPUComputeStorageTextures()</c>.</para>
        /// <para>All read-write storage textures must come after all read-only storage textures in the <c>[[texture]]</c> argument table, in order of how they are bound via <c>SDL_BeginGPUComputePass()</c>.</para>
        /// <para>All uniform buffers must come first in the <c>[[buffer]]</c> argument table, in order of their slots in <c>SDL_PushGPUComputeUniformData()</c>.</para>
        /// <para>All read-only storage buffers must come after all uniform buffers in the <c>[[buffer]]</c> argument table, in order of how they are bound via <c>SDL_BindGPUComputeStorageBuffers()</c>.</para>
        /// <para>All read-write storage buffers must come after all read-only storage buffers in the <c>[[buffer]]</c> argument table, in order of how they are bound via <c>SDL_BeginGPUComputePass()</c>.</para>
        /// <para>**Example**</para>
        /// <para>For a compute shader binding 2 of each resource type, the main function signature should look like this:</para>
        /// <code language="c++">
        /// kernel void ExampleComputeShader(
        ///     // Any samplers go in the `sampler` table, in SDL bind slot order
        ///     sampler samplerBoundToSlot0 [[sampler(0)]],
        ///     sampler samplerBoundToSlot1 [[sampler(1)]],
        ///     // Any sampled textures come first in the `texture` table, in SDL bind slot order
        ///     texture2d&lt;float> sampledTextureBoundToSlot0 [[texture(0)]],
        ///     texture2d&lt;float> sampledTextureBoundToSlot1 [[texture(1)]],
        ///     // Any read-only storage textures come next in the `texture` table, in SDL bind slot order
        ///     texture2d&lt;float> storageTextureBoundToSlot0 [[texture(2)]],
        ///     texture2d&lt;float> storageTextureBoundToSlot1 [[texture(3)]],
        ///     // Any read-write storage textures come next in the `texture` table, in SDL bind slot order
        ///     texture2d&lt;float, access::write> rwStorageTextureBoundToSlot0 [[texture(4)]];
        ///     texture2d&lt;float, access::write> rwStorageTextureBoundToSlot1 [[texture(5)]];
        ///     // Any uniform buffers come first in the `buffer` table, in SDL slot order
        ///     constant SomeUniformStruct uniformDataBoundToSlot0 [[buffer(0)]],
        ///     constant SomeUniformStruct uniformDataBoundToSlot1 [[buffer(1)]],
        ///     // Any read-only storage buffers come next in the `buffer` table, in SDL bind slot order
        ///     device SomeBufferStruct&amp; storageBufferBoundToSlot0 [[buffer(2)]],
        ///     device SomeBufferStruct&amp; storageBufferBoundToSlot1 [[buffer(3)]]);
        ///     // Any read-write storage buffers come next in the `buffer` table, in SDL bind slot order
        ///     device SomeBufferStruct&amp; rwStorageBufferBoundToSlot0 [[buffer(4)]];
        ///     device SomeBufferStruct&amp; rwStorageBufferBoundToSlot1 [[buffer(5)]]);
        /// </code>
        /// <para>---</para>
        /// <para>There are optional properties that can be provided through <c>props</c>. These are the supported properties:</para>
        /// <list type="bullet">
        /// <item><description><see cref="CSDL.Props.GPUComputepipelineCreateNameString">GPUComputepipelineCreateNameString</see>: a name that can be displayed in debugging tools.</description></item>
        /// </list>
        /// </remarks>
        /// <param name="device">a GPU Context.</param>
        /// <param name="createinfo">a struct describing the state of the compute pipeline to create.</param>
        /// <returns>
        /// <para>(<c>SDL_GPUComputePipeline</c> *) Returns a compute pipeline object on success, or NULL on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_CreateGPUComputePipeline">SDL_CreateGPUComputePipeline</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.GPU.GPUComputePass.BindComputePipeline">BindComputePipeline</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPUComputePipeline.DisposeResource">DisposeResource</see></seealso>
        public static extern void CreateGPUComputePipeline();

        /// <summary>
        /// <para>Creates a GPU context.</para>
        /// </summary>
        /// <remarks>
        /// <para>The GPU driver name can be one of the following:</para>
        /// <list type="bullet">
        /// <item><description>"vulkan": <c>CategoryGPU#vulkan</c></description></item>
        /// <item><description>"direct3d12": <c>CategoryGPU#d3d12</c></description></item>
        /// <item><description>"metal": <c>CategoryGPU#metal</c></description></item>
        /// <item><description>NULL: let SDL pick the optimal driver</description></item>
        /// </list>
        /// </remarks>
        /// <param name="format_flags">a bitflag indicating which shader formats the app is able to provide.</param>
        /// <param name="debug_mode">enable debug mode properties and validations.</param>
        /// <param name="name">the preferred GPU driver, or NULL to let SDL pick the optimal driver.</param>
        /// <returns>
        /// <para>(<c>SDL_GPUDevice</c> *) Returns a GPU context on success or NULL on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_CreateGPUDevice">SDL_CreateGPUDevice</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.GPU.GPUDevice(GPUDeviceProperties)">GPUDevice(GPUDeviceProperties)</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPUDevice.ActiveDrivers">ActiveDrivers</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPUDevice.Driver">Driver</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPUDevice.DisposeResource">DisposeResource</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPUDevice.SupportsShaderFormats">SupportsShaderFormats</see></seealso>
        public static extern void CreateGPUDevice();

        /// <summary>
        /// <para>Creates a GPU context.</para>
        /// </summary>
        /// <remarks>
        /// <para>These are the supported properties:</para>
        /// <list type="bullet">
        /// <item><description><see cref="CSDL.Props.GPUDeviceCreateDebugmodeBoolean">GPUDeviceCreateDebugmodeBoolean</see>: enable debug mode properties and validations, defaults to true.</description></item>
        /// <item><description><see cref="CSDL.Props.GPUDeviceCreatePreferlowpowerBoolean">GPUDeviceCreatePreferlowpowerBoolean</see>: enable to prefer energy efficiency over maximum GPU performance, defaults to false.</description></item>
        /// <item><description><see cref="CSDL.Props.GPUDeviceCreateVerboseBoolean">GPUDeviceCreateVerboseBoolean</see>: enable to automatically log useful debug information on device creation, defaults to true.</description></item>
        /// <item><description><see cref="CSDL.Props.GPUDeviceCreateNameString">GPUDeviceCreateNameString</see>: the name of the GPU driver to use, if a specific one is desired.</description></item>
        /// <item><description><see cref="CSDL.Props.GPUDeviceCreateFeatureClipDistanceBoolean">GPUDeviceCreateFeatureClipDistanceBoolean</see>: Enable Vulkan device feature shaderClipDistance. If disabled, clip distances are not supported in shader code: gl_ClipDistance[] built-ins of GLSL, SV_ClipDistance0/1 semantics of HLSL and [[clip_distance]] attribute of Metal. Disabling optional features allows the application to run on some older Android devices. Defaults to true.</description></item>
        /// <item><description><see cref="CSDL.Props.GPUDeviceCreateFeatureDepthClampingBoolean">GPUDeviceCreateFeatureDepthClampingBoolean</see>: Enable Vulkan device feature depthClamp. If disabled, there is no depth clamp support and enable_depth_clip in <see cref="CSDL.GPU.GPURasterizerState">GPURasterizerState</see> must always be set to true. Disabling optional features allows the application to run on some older Android devices. Defaults to true.</description></item>
        /// <item><description><see cref="CSDL.Props.GPUDeviceCreateFeatureIndirectDrawFirstInstanceBoolean">GPUDeviceCreateFeatureIndirectDrawFirstInstanceBoolean</see>: Enable Vulkan device feature drawIndirectFirstInstance. If disabled, the argument first_instance of <see cref="CSDL.GPU.GPUIndirectDrawCommand">GPUIndirectDrawCommand</see> must be set to zero. Disabling optional features allows the application to run on some older Android devices. Defaults to true.</description></item>
        /// <item><description><see cref="CSDL.Props.GPUDeviceCreateFeatureAnisotropyBoolean">GPUDeviceCreateFeatureAnisotropyBoolean</see>: Enable Vulkan device feature samplerAnisotropy. If disabled, enable_anisotropy of <see cref="CSDL.GPU.GPUSamplerCreateInfo">GPUSamplerCreateInfo</see> must be set to false. Disabling optional features allows the application to run on some older Android devices. Defaults to true.</description></item>
        /// </list>
        /// <para>These are the current shader format properties:</para>
        /// <list type="bullet">
        /// <item><description><see cref="CSDL.Props.GPUDeviceCreateShadersPrivateBoolean">GPUDeviceCreateShadersPrivateBoolean</see>: The app is able to provide shaders for an NDA platform.</description></item>
        /// <item><description><see cref="CSDL.Props.GPUDeviceCreateShadersSpirvBoolean">GPUDeviceCreateShadersSpirvBoolean</see>: The app is able to provide SPIR-V shaders if applicable.</description></item>
        /// <item><description><see cref="CSDL.Props.GPUDeviceCreateShadersDxbcBoolean">GPUDeviceCreateShadersDxbcBoolean</see>: The app is able to provide DXBC shaders if applicable</description></item>
        /// <item><description><see cref="CSDL.Props.GPUDeviceCreateShadersDxilBoolean">GPUDeviceCreateShadersDxilBoolean</see>: The app is able to provide DXIL shaders if applicable.</description></item>
        /// <item><description><see cref="CSDL.Props.GPUDeviceCreateShadersMslBoolean">GPUDeviceCreateShadersMslBoolean</see>: The app is able to provide MSL shaders if applicable.</description></item>
        /// <item><description><see cref="CSDL.Props.GPUDeviceCreateShadersMetallibBoolean">GPUDeviceCreateShadersMetallibBoolean</see>: The app is able to provide Metal shader libraries if applicable.</description></item>
        /// </list>
        /// <para>With the D3D12 backend:</para>
        /// <list type="bullet">
        /// <item><description><see cref="CSDL.Props.GPUDeviceCreateD3D12SemanticNameString">GPUDeviceCreateD3D12SemanticNameString</see>: the prefix to use for all vertex semantics, default is "TEXCOORD".</description></item>
        /// <item><description><see cref="CSDL.Props.GPUDeviceCreateD3D12AllowFewerResourceSlotsBoolean">GPUDeviceCreateD3D12AllowFewerResourceSlotsBoolean</see>: By default, Resourcing Binding Tier 2 is required for D3D12 support. However, an application can set this property to true to enable Tier 1 support, if (and only if) the application uses 8 or fewer storage resources across all shader stages. As of writing, this property is useful for targeting Intel Haswell and Broadwell GPUs; other hardware either supports Tier 2 Resource Binding or does not support D3D12 in any capacity. Defaults to false.</description></item>
        /// <item><description><see cref="CSDL.Props.GPUDeviceCreateD3D12AgilitySdkVersionNumber">GPUDeviceCreateD3D12AgilitySdkVersionNumber</see>: Certain feature checks are only possible on Windows 11 by default. By setting this alongside <see cref="CSDL.Props.GPUDeviceCreateD3D12AgilitySdkPathString">GPUDeviceCreateD3D12AgilitySdkPathString</see> and vendoring D3D12Core.dll from the D3D12 Agility SDK, you can make those feature checks possible on older platforms. The version you provide must match the one given in the DLL.</description></item>
        /// <item><description><see cref="CSDL.Props.GPUDeviceCreateD3D12AgilitySdkPathString">GPUDeviceCreateD3D12AgilitySdkPathString</see>: Certain feature checks are only possible on Windows 11 by default. By setting this alongside <see cref="CSDL.Props.GPUDeviceCreateD3D12AgilitySdkVersionNumber">GPUDeviceCreateD3D12AgilitySdkVersionNumber</see> and vendoring D3D12Core.dll from the D3D12 Agility SDK, you can make those feature checks possible on older platforms. The path you provide must be relative to the executable path of your app. Be sure not to put the DLL in the same directory as the exe; Microsoft strongly advises against this!</description></item>
        /// </list>
        /// <para>With the Vulkan backend:</para>
        /// <list type="bullet">
        /// <item><description><see cref="CSDL.Props.GPUDeviceCreateVulkanRequireHardwareAccelerationBoolean">GPUDeviceCreateVulkanRequireHardwareAccelerationBoolean</see>: By default, Vulkan device enumeration includes drivers of all types, including software renderers (for example, the Lavapipe Mesa driver). This can be useful if your application _requires_ <c>SDL_GPU</c>, but if you can provide your own fallback renderer (for example, an OpenGL renderer) this property can be set to true. Defaults to false.</description></item>
        /// <item><description><see cref="CSDL.Props.GPUDeviceCreateVulkanOptionsPointer">GPUDeviceCreateVulkanOptionsPointer</see>: a pointer to an <see cref="CSDL.GPU.GPUVulkanOptions">GPUVulkanOptions</see> structure to be processed during device creation. This allows configuring a variety of Vulkan-specific options such as increasing the API version and opting into extensions aside from the minimal set SDL requires.</description></item>
        /// </list>
        /// <para>With the Metal backend: - <see cref="CSDL.Props.GPUDeviceCreateMetalAllowMACFAMILY1Boolean">GPUDeviceCreateMetalAllowMACFAMILY1Boolean</see>: By default, macOS support requires what Apple calls "MTLGPUFamilyMac2" hardware or newer. However, an application can set this property to true to enable support for "MTLGPUFamilyMac1" hardware, if (and only if) the application does not write to sRGB textures. (For history's sake: MacFamily1 also does not support indirect command buffers, MSAA depth resolve, and stencil resolve/feedback, but these are not exposed features in <c>SDL_GPU</c>.)</para>
        /// </remarks>
        /// <param name="props">the properties to use.</param>
        /// <returns>
        /// <para>(<c>SDL_GPUDevice</c> *) Returns a GPU context on success or NULL on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_CreateGPUDeviceWithProperties">SDL_CreateGPUDeviceWithProperties</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.GPU.GPUDevice.ActiveDrivers">ActiveDrivers</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPUDevice.Driver">Driver</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPUDevice.DisposeResource">DisposeResource</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPUDevice.SupportsProperties">SupportsProperties</see></seealso>
        public static extern void CreateGPUDeviceWithProperties();

