        /// <summary>
        /// <para>Creates a shader to be used when creating a graphics pipeline.</para>
        /// </summary>
        /// <remarks>
        /// <para>Shader resource bindings must be authored to follow a particular convention depending on the shader format. See below for details.</para>
        /// <para>---</para>
        /// <para>**SPIR-V**</para>
        /// <para>For vertex shaders, use: - Set 0 for samplers, storage textures, and storage buffers - Set 1 for uniform data</para>
        /// <para>For fragment shaders, use: - Set 2 for samplers, storage textures, and storage buffers - Set 3 for uniform data</para>
        /// <para>The first resource in a given set must have a <c>binding</c> of 0. Additional resources must appear at consecutive bindings (1, 2, etc), leaving no gaps in the set.</para>
        /// <para>All samplers must come first in the binding order, in order of how they are bound via <c>SDL_BindGPU*Samplers()</c>.</para>
        /// <para>All storage textures must come after all samplers in the binding order, in order of how they are bound via <c>SDL_Bind*StorageTextures()</c>.</para>
        /// <para>All storage buffers must come after all storage textures in the binding order, in order of how they are bound via <c>SDL_Bind*StorageBuffers()</c>.</para>
        /// <para>**Example**</para>
        /// <para>If a vertex shader binds 2 samplers, 2 storage textures, 2 storage buffers, and 2 uniform buffers, its binding layout should look like this:</para>
        /// <code language="glsl">
        /// // Any samplers come first in the set, in SDL bind slot order
        /// layout(set = 0, binding = 0) sampler2d samplerBoundToSlot0;
        /// layout(set = 0, binding = 1) sampler2d samplerBoundToSlot1;
        /// // Any storage textures come next in the set, in SDL bind slot order
        /// layout(set = 0, binding = 2) texture2d storageTextureBoundToSlot0;
        /// layout(set = 0, binding = 3) texture2d storageTextureBoundToSlot1;
        /// // Any storage buffers come next in the set, in SDL bind slot order
        /// layout(set = 0, binding = 4) buffer storageBufferBoundToSlot0;
        /// layout(set = 0, binding = 5) buffer storageBufferBoundToSlot1;
        /// // Any uniform buffers are in their own set, in SDL slot order
        /// layout(set = 1, binding = 0) uniform UniformDataBoundToSlot0 {};
        /// layout(set = 1, binding = 1) uniform UniformDataBoundToSlot1 {};
        /// </code>
        /// <para>---</para>
        /// <para>**DXBC / DXIL (HLSL)**</para>
        /// <para>For vertex shaders, use: - <c>(t[n], space0)</c> for sampled textures, storage textures, and storage buffers - <c>(s[n], space0)</c> for samplers - <c>(b[n], space1)</c> for uniform data</para>
        /// <para>For fragment (aka "pixel") shaders, use: - <c>(t[n], space2)</c> for sampled textures, storage textures, and storage buffers - <c>(s[n], space2)</c> for samplers - <c>(b[n], space3)</c> for uniform data</para>
        /// <para>The first resource in a given register set must have a register index of <c>0</c>. Additional resources must appear at consecutive indices (1, 2, etc), leaving no gaps in the register set.</para>
        /// <para>All sampled textures must come first in the <c>t</c> register set, in order of how they are bound via <c>SDL_BindGPU*Samplers()</c>.</para>
        /// <para>All sampler objects must be in the <c>s</c> register set, in the same order as the textures above.</para>
        /// <para>All storage textures must come after all samplers in the <c>t</c> register set, in order of how they are bound via <c>SDL_Bind*StorageTextures()</c>.</para>
        /// <para>All storage buffers must come after all storage textures in the <c>t</c> register set, in order of how they are bound via <c>SDL_Bind*StorageBuffers()</c>.</para>
        /// <para>**Example**</para>
        /// <para>If a pixel shader binds 2 samplers, 2 storage textures, 2 storage buffers, and 2 uniform buffers, its binding layout should look like this:</para>
        /// <code language="c">
        /// // Any samplers and sampled textures come first in their respective register sets, in SDL bind slot order
        /// SamplerState SamplerBoundToSlot0 : register( s0, space2 );
        /// SamplerState SamplerBoundToSlot1 : register( s1, space2 );
        /// Texture2D SampledTextureBoundToSlot0 : register( t0, space2 );
        /// Texture2D SampledTextureBoundToSlot1 : register( t1, space2 );
        /// // Any storage textures come next in the `t` register set, in SDL bind slot order
        /// Texture2D StorageTextureBoundToSlot0 : register( t2, space2 );
        /// Texture2D StorageTextureBoundToSlot1 : register( t3, space2 );
        /// // Any storage buffers come next in the `t` register set, in SDL bind slot order
        /// ByteAddressBuffer StorageBufferBoundToSlot0 : register( t4, space2 );
        /// ByteAddressBuffer StorageBufferBoundToSlot1 : register( t5, space2 );
        /// // Any uniform buffers are in the `b` register set *and* in their own space, in SDL slot order
        /// cbuffer UniformDataBoundToSlot0 : register( b0, space4 ) { ... };
        /// cbuffer UniformDataBoundToSlot1 : register( b1, space4 ) { ... };
        /// </code>
        /// <para>---</para>
        /// <para>**MSL / Metallib (Metal Shading Language)**</para>
        /// <para>The first resource in a given argument table must have an index of <c>0</c>. Additional resources must appear at consecutive indices (1, 2, etc), leaving no gaps in the table. (_Except_ in the case of vertex buffers, which are mentioned below.)</para>
        /// <para>All sampled textures must come first in the <c>[[texture]]</c> argument table, in order of how they are bound via <c>SDL_BindGPU*Samplers()</c>.</para>
        /// <para>All sampler objects must be in the <c>[[sampler]]</c> argument table, in the same order as the textures above.</para>
        /// <para>All storage textures must come after all sampled textures in the <c>[[texture]]</c> argument table, in order of how they are bound via <c>SDL_BindGPU*StorageTextures()</c>.</para>
        /// <para>All uniform buffers must come first in the <c>[[buffer]]</c> argument table, in order of their slots in <c>SDL_PushGPU*UniformData()</c>.</para>
        /// <para>All storage buffers must come after all uniform buffers in the <c>[[buffer]]</c> argument table, in order of how they are bound via <c>SDL_BindGPU*StorageBuffers()</c>.</para>
        /// <para>In Metal, vertex buffers are also included in the <c>[[buffer]]</c> argument table. To work around this, SDL forces the vertex buffer bound to slot 0 to be bound at <c>[[buffer(14)]]</c>. The vertex buffer in slot 1 will be bound to <c>[[buffer(15)]]</c>, and so on. Rather than manually authoring vertex buffer indices, use the <c>[[stage_in]]</c> attribute which will automatically use the vertex input information from the <c>SDL_GPUGraphicsPipeline</c>.</para>
        /// <para>**Example**</para>
        /// <para>For a vertex shader with 1 vertex buffer, 2 samplers, 2 storage textures, 2 storage buffers, and 2 uniform buffers, the main function signature should look something like this:</para>
        /// <code language="c++">
        /// vertex VertexOutput ExampleVertexShader(
        ///     // Vertex buffers are their own special thing...
        ///     SomeVertexInput input [[stage_in]], // alternatively, SomeVertexInput input [[buffer(14)]]
        ///     // Any samplers go in the `sampler` table, in SDL bind slot order
        ///     sampler samplerBoundToSlot0 [[sampler(0)]],
        ///     sampler samplerBoundToSlot1 [[sampler(1)]],
        ///     // Any sampled textures come first in the `texture` table, in SDL bind slot order
        ///     texture2d&lt;float> sampledTextureBoundToSlot0 [[texture(0)]],
        ///     texture2d&lt;float> sampledTextureBoundToSlot1 [[texture(1)]],
        ///     // Any storage textures come next in the `texture` table, in SDL bind slot order
        ///     texture2d&lt;float> storageTextureBoundToSlot0 [[texture(2)]],
        ///     texture2d&lt;float> storageTextureBoundToSlot1 [[texture(3)]],
        ///     // Any uniform buffers come first in the `buffer` table, in SDL slot order
        ///     constant SomeUniformStruct uniformDataBoundToSlot0 [[buffer(0)]],
        ///     constant SomeUniformStruct uniformDataBoundToSlot1 [[buffer(1)]],
        ///     // Any storage buffers come next in the `buffer` table, in SDL bind slot order
        ///     device SomeBufferStruct&amp; storageBufferBoundToSlot0 [[buffer(2)]],
        ///     device SomeBufferStruct&amp; storageBufferBoundToSlot1 [[buffer(3)]]);
        /// 
        /// </code>
        /// <para>---</para>
        /// <para>Shader semantics other than system-value semantics do not matter in D3D12. For ease of use, the SDL implementation assumes that non system-value semantics will all be <c>TEXCOORD</c>. If you are using HLSL as the shader source language, your vertex semantics should start at <c>TEXCOORD0</c> and increment like so: <c>TEXCOORD1</c>, <c>TEXCOORD2</c>, etc.</para>
        /// <para>If you wish to change the semantic prefix to something other than <c>TEXCOORD</c> you can use <see cref="CSDL.Props.GPUDeviceCreateD3D12SemanticNameString">GPUDeviceCreateD3D12SemanticNameString</see> with <see cref="CSDL.GPU.GPUDevice(GPUDeviceProperties)">GPUDevice(GPUDeviceProperties)</see>.</para>
        /// <para>There are optional properties that can be provided through <c>props</c>. These are the supported properties:</para>
        /// <list type="bullet">
        /// <item><description><see cref="CSDL.Props.GPUShaderCreateNameString">GPUShaderCreateNameString</see>: a name that can be displayed in debugging tools.</description></item>
        /// </list>
        /// </remarks>
        /// <param name="device">a GPU Context.</param>
        /// <param name="createinfo">a struct describing the state of the shader to create.</param>
        /// <returns>
        /// <para>(<see cref="CSDL.GPU.GPUShader">GPUShader</see> *) Returns a shader object on success, or NULL on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_CreateGPUShader">SDL_CreateGPUShader</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.GPU.GPUGraphicsPipeline(GPUDevice,in GPUGraphicsPipelineCreateInfo)">GPUGraphicsPipeline(GPUDevice,in GPUGraphicsPipelineCreateInfo)</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPUShader.DisposeResource">DisposeResource</see></seealso>
        public static extern void CreateGPUShader();

        /// <summary>
        /// <para>Creates a texture object to be used in graphics or compute workflows.</para>
        /// </summary>
        /// <remarks>
        /// <para>The contents of this texture are undefined until data is written to the texture, either via <see cref="CSDL.GPU.GPURenderer.UploadToTexture">UploadToTexture</see> or by performing a render or compute pass with this texture as a target.</para>
        /// <para>Note that certain combinations of usage flags are invalid. For example, a texture cannot have both the SAMPLER and GRAPHICS_STORAGE_READ flags.</para>
        /// <para>If you request a sample count higher than the hardware supports, the implementation will automatically fall back to the highest available sample count.</para>
        /// <para>There are optional properties that can be provided through <see cref="CSDL.GPU.GPUTextureCreateInfo">GPUTextureCreateInfo</see>'s <c>props</c>. These are the supported properties:</para>
        /// <list type="bullet">
        /// <item><description><see cref="CSDL.Props.GPUTextureCreateD3D12ClearRFloat">GPUTextureCreateD3D12ClearRFloat</see>: (Direct3D 12 only) if the texture usage is <c>SDL_GPU_TEXTUREUSAGE_COLOR_TARGET</c>, clear the texture to a color with this red intensity. Defaults to zero.</description></item>
        /// <item><description><see cref="CSDL.Props.GPUTextureCreateD3D12ClearGFloat">GPUTextureCreateD3D12ClearGFloat</see>: (Direct3D 12 only) if the texture usage is <c>SDL_GPU_TEXTUREUSAGE_COLOR_TARGET</c>, clear the texture to a color with this green intensity. Defaults to zero.</description></item>
        /// <item><description><see cref="CSDL.Props.GPUTextureCreateD3D12ClearBFloat">GPUTextureCreateD3D12ClearBFloat</see>: (Direct3D 12 only) if the texture usage is <c>SDL_GPU_TEXTUREUSAGE_COLOR_TARGET</c>, clear the texture to a color with this blue intensity. Defaults to zero.</description></item>
        /// <item><description><see cref="CSDL.Props.GPUTextureCreateD3D12ClearAFloat">GPUTextureCreateD3D12ClearAFloat</see>: (Direct3D 12 only) if the texture usage is <c>SDL_GPU_TEXTUREUSAGE_COLOR_TARGET</c>, clear the texture to a color with this alpha intensity. Defaults to zero.</description></item>
        /// <item><description><see cref="CSDL.Props.GPUTextureCreateD3D12ClearDepthFloat">GPUTextureCreateD3D12ClearDepthFloat</see>: (Direct3D 12 only) if the texture usage is <c>SDL_GPU_TEXTUREUSAGE_DEPTH_STENCIL_TARGET</c>, clear the texture to a depth of this value. Defaults to zero.</description></item>
        /// <item><description><see cref="CSDL.Props.GPUTextureCreateD3D12ClearStencilNumber">GPUTextureCreateD3D12ClearStencilNumber</see>: (Direct3D 12 only) if the texture usage is <c>SDL_GPU_TEXTUREUSAGE_DEPTH_STENCIL_TARGET</c>, clear the texture to a stencil of this Uint8 value. Defaults to zero.</description></item>
        /// <item><description><see cref="CSDL.Props.GPUTextureCreateNameString">GPUTextureCreateNameString</see>: a name that can be displayed in debugging tools.</description></item>
        /// </list>
        /// </remarks>
        /// <param name="device">a GPU Context.</param>
        /// <param name="createinfo">a struct describing the state of the texture to create.</param>
        /// <returns>
        /// <para>(<see cref="CSDL.GPU.GPUTexture">GPUTexture</see> *) Returns a texture object on success, or NULL on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_CreateGPUTexture">SDL_CreateGPUTexture</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.GPU.GPURenderer.UploadToTexture">UploadToTexture</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPURenderer.DownloadFromTexture">DownloadFromTexture</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPUCommandBuffer.BeginRenderPass">BeginRenderPass</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPUCommandBuffer.BeginComputePass">BeginComputePass</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPURenderPass.BindVertexSamplers">BindVertexSamplers</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPURenderPass.BindVertexStorageTextures">BindVertexStorageTextures</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPURenderPass.BindFragmentSamplers">BindFragmentSamplers</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPURenderPass.BindFragmentStorageTextures">BindFragmentStorageTextures</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPUComputePass.BindComputeStorageTextures">BindComputeStorageTextures</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPUCommandBuffer.BlitGPUTexture">BlitGPUTexture</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPUTexture.DisposeResource">DisposeResource</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPUDevice.TextureSupportsFormat">TextureSupportsFormat</see></seealso>
        public static extern void CreateGPUTexture();

        /// <summary>
        /// <para>Creates a transfer buffer to be used when uploading to or downloading from graphics resources.</para>
