        /// </returns>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_CreateGPUTransferBuffer">SDL_CreateGPUTransferBuffer</seealso></SDLWiki>
