        public static extern void CreateGPUTransferBuffer();

        /// <summary>
        /// <para>Destroys a GPU context previously returned by <see cref="CSDL.GPU.GPUDevice(GPUShaderFormat,bool,string?)">GPUDevice(GPUShaderFormat,bool,string?)</see>.</para>
        /// </summary>
