        /// <summary>
        /// <para>Dispatches compute work.</para>
        /// </summary>
        /// <remarks>
        /// <para>You must not call this function before binding a compute pipeline.</para>
        /// <para>A VERY IMPORTANT NOTE If you dispatch multiple times in a compute pass, and the dispatches write to the same resource region as each other, there is no guarantee of which order the writes will occur. If the write order matters, you MUST end the compute pass and begin another one.</para>
        /// </remarks>
        /// <param name="compute_pass">a compute pass handle.</param>
        /// <param name="groupcount_x">number of local workgroups to dispatch in the X dimension.</param>
        /// <param name="groupcount_y">number of local workgroups to dispatch in the Y dimension.</param>
        /// <param name="groupcount_z">number of local workgroups to dispatch in the Z dimension.</param>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_DispatchGPUCompute">SDL_DispatchGPUCompute</seealso></SDLWiki>
        public static extern void DispatchGPUCompute();

        /// <summary>
        /// <para>Dispatches compute work with parameters set from a buffer.</para>
