        /// <remarks>
        /// <para>The buffer layout should match the layout of <see cref="CSDL.GPU.GPUIndirectDispatchCommand">GPUIndirectDispatchCommand</see>. You must not call this function before binding a compute pipeline.</para>
        /// <para>A VERY IMPORTANT NOTE If you dispatch multiple times in a compute pass, and the dispatches write to the same resource region as each other, there is no guarantee of which order the writes will occur. If the write order matters, you MUST end the compute pass and begin another one.</para>
        /// </remarks>
        /// <param name="compute_pass">a compute pass handle.</param>
        /// <param name="buffer">a buffer containing dispatch parameters.</param>
        /// <param name="offset">the offset to start reading from the dispatch buffer.</param>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_DispatchGPUComputeIndirect">SDL_DispatchGPUComputeIndirect</seealso></SDLWiki>
        public static extern void DispatchGPUComputeIndirect();

        /// <summary>
        /// <para>Copies data from a buffer to a transfer buffer on the GPU timeline.</para>
        /// </summary>
        /// <remarks>
        /// <para>This data is not guaranteed to be copied until the command buffer fence is signaled.</para>
        /// </remarks>
        /// <param name="copy_pass">a copy pass handle.</param>
        /// <param name="source">the source buffer with offset and size.</param>
        /// <param name="destination">the destination transfer buffer with offset.</param>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_DownloadFromGPUBuffer">SDL_DownloadFromGPUBuffer</seealso></SDLWiki>
        public static extern void DownloadFromGPUBuffer();

        /// <summary>
        /// <para>Copies data from a texture to a transfer buffer on the GPU timeline.</para>
