        /// <para>This data is not guaranteed to be copied until the command buffer fence is signaled.</para>
        /// </remarks>
        /// <param name="copy_pass">a copy pass handle.</param>
        /// <param name="source">the source texture region.</param>
        /// <param name="destination">the destination transfer buffer with image layout information.</param>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_DownloadFromGPUTexture">SDL_DownloadFromGPUTexture</seealso></SDLWiki>
        public static extern void DownloadFromGPUTexture();

        /// <summary>
        /// <para>Draws data using bound graphics state with an index buffer and instancing enabled.</para>
        /// </summary>
        /// <remarks>
        /// <para>You must not call this function before binding a graphics pipeline.</para>
