        /// <summary>
        /// <para>Get the properties associated with a GPU device.</para>
        /// </summary>
        /// <remarks>
        /// <para>All properties are optional and may differ between GPU backends and SDL versions.</para>
        /// <para>The following properties are provided by SDL:</para>
        /// <para><see cref="CSDL.Props.GPUDeviceNameString">GPUDeviceNameString</see>: Contains the name of the underlying device as reported by the system driver. This string has no standardized format, is highly inconsistent between hardware devices and drivers, and is able to change at any time. Do not attempt to parse this string as it is bound to fail at some point in the future when system drivers are updated, new hardware devices are introduced, or when SDL adds new GPU backends or modifies existing ones.</para>
        /// <para>Strings that have been found in the wild include:</para>
        /// <list type="bullet">
        /// <item><description>GTX 970</description></item>
        /// <item><description>GeForce GTX 970</description></item>
        /// <item><description>NVIDIA GeForce GTX 970</description></item>
        /// <item><description>Microsoft Direct3D12 (NVIDIA GeForce GTX 970)</description></item>
        /// <item><description>NVIDIA Graphics Device</description></item>
        /// <item><description>GeForce GPU</description></item>
        /// <item><description>P106-100</description></item>
        /// <item><description>AMD 15D8:C9</description></item>
        /// <item><description>AMD Custom GPU 0405</description></item>
        /// <item><description>AMD Radeon (TM) Graphics</description></item>
        /// <item><description>ASUS Radeon RX 470 Series</description></item>
        /// <item><description>Intel(R) Arc(tm) A380 Graphics (DG2)</description></item>
        /// <item><description>Virtio-GPU Venus (NVIDIA TITAN V)</description></item>
        /// <item><description>SwiftShader Device (LLVM 16.0.0)</description></item>
        /// <item><description>llvmpipe (LLVM 15.0.4, 256 bits)</description></item>
        /// <item><description>Microsoft Basic Render Driver</description></item>
        /// <item><description>unknown device</description></item>
        /// </list>
        /// <para>The above list shows that the same device can have different formats, the vendor name may or may not appear in the string, the included vendor name may not be the vendor of the chipset on the device, some manufacturers include pseudo-legal marks while others don't, some devices may not use a marketing name in the string, the device string may be wrapped by the name of a translation interface, the device may be emulated in software, or the string may contain generic text that does not identify the device at all.</para>
        /// <para><see cref="CSDL.Props.GPUDeviceDriverNameString">GPUDeviceDriverNameString</see>: Contains the self-reported name of the underlying system driver.</para>
        /// <para>Strings that have been found in the wild include:</para>
        /// <list type="bullet">
        /// <item><description>Intel Corporation</description></item>
        /// <item><description>Intel open-source Mesa driver</description></item>
        /// <item><description>Qualcomm Technologies Inc. Adreno Vulkan Driver</description></item>
        /// <item><description>MoltenVK</description></item>
        /// <item><description>Mali-G715</description></item>
        /// <item><description>venus</description></item>
        /// </list>
        /// <para><see cref="CSDL.Props.GPUDeviceDriverVersionString">GPUDeviceDriverVersionString</see>: Contains the self-reported version of the underlying system driver. This is a relatively short version string in an unspecified format. If <see cref="CSDL.Props.GPUDeviceDriverInfoString">GPUDeviceDriverInfoString</see> is available then that property should be preferred over this one as it may contain additional information that is useful for identifying the exact driver version used.</para>
        /// <para>Strings that have been found in the wild include:</para>
        /// <list type="bullet">
        /// <item><description>53.0.0</description></item>
        /// <item><description>0.405.2463</description></item>
        /// <item><description>32.0.15.6614</description></item>
        /// </list>
        /// <para><see cref="CSDL.Props.GPUDeviceDriverInfoString">GPUDeviceDriverInfoString</see>: Contains the detailed version information of the underlying system driver as reported by the driver. This is an arbitrary string with no standardized format and it may contain newlines. This property should be preferred over <see cref="CSDL.Props.GPUDeviceDriverVersionString">GPUDeviceDriverVersionString</see> if it is available as it usually contains the same information but in a format that is easier to read.</para>
        /// <para>Strings that have been found in the wild include:</para>
        /// <list type="bullet">
        /// <item><description>101.6559</description></item>
        /// <item><description>1.2.11</description></item>
        /// <item><description>Mesa 21.2.2 (LLVM 12.0.1)</description></item>
        /// <item><description>Mesa 22.2.0-devel (git-f226222 2022-04-14 impish-oibaf-ppa)</description></item>
        /// <item><description>v1.r53p0-00eac0.824c4f31403fb1fbf8ee1042422c2129</description></item>
        /// </list>
        /// <para>This string has also been observed to be a multiline string (which has a trailing newline):</para>
        /// <code>
        /// Driver Build: 85da404, I46ff5fc46f, 1606794520
        /// Date: 11/30/20
        /// Compiler Version: EV031.31.04.01
        /// Driver Branch: promo490_3_Google
        /// </code>
        /// </remarks>
        /// <param name="device">a GPU context to query.</param>
        /// <returns>
        /// <para>(<see cref="CSDL.PropertiesID">PropertiesID</see>) Returns a valid property ID on success or 0 on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL 3.4.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_GetGPUDeviceProperties">SDL_GetGPUDeviceProperties</seealso></SDLWiki>
        public static extern void GetGPUDeviceProperties();

