        /// <summary>
        /// <para>Blocks the thread until the given fences are signaled.</para>
        /// </summary>
        /// <param name="device">a GPU context.</param>
        /// <param name="wait_all">if 0, wait for any fence to be signaled, if 1, wait for all fences to be signaled.</param>
        /// <param name="fences">an array of fences to wait on.</param>
        /// <param name="num_fences">the number of fences in the fences array.</param>
        /// <returns>
        /// <para>(bool) Returns true on success, false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_WaitForGPUFences">SDL_WaitForGPUFences</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.GPU.GPUCommandBuffer.SubmitAndAcquireFence">SubmitAndAcquireFence</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPUDevice.WaitForIdle">WaitForIdle</see></seealso>
        public static extern void WaitForGPUFences();

        /// <summary>
        /// <para>Blocks the thread until the GPU is completely idle.</para>
        /// </summary>
        /// <param name="device">a GPU context.</param>
        /// <returns>
        /// <para>(bool) Returns true on success, false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_WaitForGPUIdle">SDL_WaitForGPUIdle</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.GPU.GPURenderer.WaitForFences">WaitForFences</see></seealso>
        public static extern void WaitForGPUIdle();

        /// <summary>
        /// <para>Blocks the thread until all presenting command buffers are finished executing.</para>
        /// </summary>
        /// <param name="device">a GPU context.</param>
        /// <param name="window">a window that has been claimed.</param>
        /// <returns>
        /// <para>(bool) Returns true on success, false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>This function should only be called from the thread that created the window.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_WaitForGPUSwapchain">SDL_WaitForGPUSwapchain</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.GPU.GPURenderer.AcquireSwapchainTexture">AcquireSwapchainTexture</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPURenderer.WaitAndAcquireSwapchainTexture">WaitAndAcquireSwapchainTexture</see></seealso>
        /// <seealso><see cref="CSDL.GPU.GPUDevice.SetAllowedFramesInFlight">SetAllowedFramesInFlight</see></seealso>
        public static extern void WaitForGPUSwapchain();

        /// <summary>
        /// <para>Determines whether a presentation mode is supported by the window.</para>
        /// </summary>
        /// <remarks>
        /// <para>The window must be claimed before calling this function.</para>
        /// </remarks>
        /// <param name="device">a GPU context.</param>
        /// <param name="window">an <c>SDL_Window</c>.</param>
        /// <param name="present_mode">the presentation mode to check.</param>
        /// <returns>
        /// <para>(bool) Returns true if supported, false if unsupported.</para>
        /// </returns>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_WindowSupportsGPUPresentMode">SDL_WindowSupportsGPUPresentMode</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.GPU.GPUDevice.ClaimWindow">ClaimWindow</see></seealso>
        public static extern void WindowSupportsGPUPresentMode();

        /// <summary>
        /// <para>Determines whether a swapchain composition is supported by the window.</para>
        /// </summary>
        /// <remarks>
        /// <para>The window must be claimed before calling this function.</para>
        /// </remarks>
        /// <param name="device">a GPU context.</param>
        /// <param name="window">an <c>SDL_Window</c>.</param>
        /// <param name="swapchain_composition">the swapchain composition to check.</param>
        /// <returns>
        /// <para>(bool) Returns true if supported, false if unsupported.</para>
        /// </returns>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_WindowSupportsGPUSwapchainComposition">SDL_WindowSupportsGPUSwapchainComposition</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.GPU.GPUDevice.ClaimWindow">ClaimWindow</see></seealso>
        public static extern void WindowSupportsGPUSwapchainComposition();
    }
}
